solution.solution.cpp:
#include <cctype>
#include <string>
#include <vector>

struct Chord { bool ctrl{ false }, shift{ false }, alt{ false }; std::string key; };

static std::string trim(const std::string& s)
{
    const auto a{ s.find_first_not_of(' ') };
    if (a == std::string::npos) return "";
    return s.substr(a, s.find_last_not_of(' ') - a + 1);
}

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

bool parseShortcut(const std::string& text, Chord& out)
{
    std::vector<std::string> parts;
    std::string current;
    for (char c : text) { if (c == '+') { parts.push_back(trim(current)); current.clear(); } else current += c; }
    parts.push_back(trim(current));
    Chord ch;
    for (std::size_t i{ 0 }; i < parts.size(); ++i)
    {
        const std::string p{ lower(parts[i]) };
        const bool last{ i + 1 == parts.size() };
        if (!last)
        {
            if ((p == "ctrl" || p == "control") && !ch.ctrl) ch.ctrl = true;
            else if (p == "shift" && !ch.shift) ch.shift = true;
            else if (p == "alt" && !ch.alt) ch.alt = true;
            else return false;
            continue;
        }
        if (p.size() == 1 && std::isalnum(static_cast<unsigned char>(p[0]))) ch.key = std::string(1, static_cast<char>(std::toupper(static_cast<unsigned char>(p[0]))));
        else if (p.size() >= 2 && p.size() <= 3 && p[0] == 'f' && std::isdigit(static_cast<unsigned char>(p[1])) && (p.size() == 2 || std::isdigit(static_cast<unsigned char>(p[2]))))
        {
            const int n{ std::stoi(p.substr(1)) };
            if (n < 1 || n > 12) return false;
            ch.key = "F" + std::to_string(n);
        }
        else if (p == "enter") ch.key = "Enter";
        else if (p == "escape") ch.key = "Escape";
        else if (p == "space") ch.key = "Space";
        else if (p == "tab") ch.key = "Tab";
        else if (p == "delete") ch.key = "Delete";
        else return false;
    }
    out = ch;
    return true;
}

std::string formatShortcut(const Chord& c)
{
    std::string s;
    if (c.ctrl) s += "Ctrl+";
    if (c.shift) s += "Shift+";
    if (c.alt) s += "Alt+";
    return s + c.key;
}

unitTests:
TEST("Ctrl+Shift+S") { Chord c; CHECK(parseShortcut("Ctrl+Shift+S", c)); CHECK(c.ctrl); CHECK(c.shift); CHECK(!c.alt); CHECK_EQ(c.key, std::string("S")); }
TEST("spaces and case") { Chord c; CHECK(parseShortcut(" control + z ", c)); CHECK(c.ctrl); CHECK_EQ(c.key, std::string("Z")); }
TEST("named keys") { Chord c; CHECK(parseShortcut("F5", c)); CHECK_EQ(c.key, std::string("F5")); CHECK(parseShortcut("alt+f12", c)); CHECK_EQ(c.key, std::string("F12")); CHECK(parseShortcut("Shift+Delete", c)); CHECK_EQ(c.key, std::string("Delete")); CHECK(parseShortcut("escape", c)); CHECK_EQ(c.key, std::string("Escape")); }
TEST("rejected") { Chord c; CHECK(!parseShortcut("", c)); CHECK(!parseShortcut("Ctrl+", c)); CHECK(!parseShortcut("Ctrl+Ctrl+S", c)); CHECK(!parseShortcut("S+Ctrl", c)); CHECK(!parseShortcut("F13", c)); CHECK(!parseShortcut("Ctrl+Banana", c)); CHECK(!parseShortcut("F0", c)); }
TEST("format") { Chord c; parseShortcut("shift+alt+ctrl+k", c); CHECK_EQ(formatShortcut(c), std::string("Ctrl+Shift+Alt+K")); Chord d; d.key = "F2"; CHECK_EQ(formatShortcut(d), std::string("F2")); }

